<?php require __DIR__.'/../app/bootstrap.php';$u=require_admin();$title=t('User directory');$users=all('SELECT id,full_name,email,phone,role,verified_at,created_at FROM users ORDER BY id DESC');require ROOT.'/app/workspace-start.php'; ?>
<div class="page-heading"><h1><?=e(t('User directory'))?></h1><p><?=e(t('People joining your food community.'))?></p></div><section class="panel"><div class="table-wrap"><table><thead><tr><th><?=e(t('Name'))?></th><th><?=e(t('Email'))?></th><th><?=e(t('Phone'))?></th><th><?=e(t('Role'))?></th><th><?=e(t('Email verified'))?></th><th><?=e(t('Joined'))?></th></tr></thead><tbody><?php foreach($users as $person): ?><tr><td><?=e($person['full_name'])?></td><td><?=e($person['email'])?></td><td><?=e($person['phone'])?></td><td><?=e(t(ucfirst($person['role'])))?></td><td><?=$person['verified_at']?'Yes':'No'?></td><td><?=e(local_time($person['created_at']))?></td></tr><?php endforeach ?></tbody></table></div></section><?php require ROOT.'/app/workspace-end.php'; ?>
